#!/usr/bin/env bash
# Generated by tungo-sdkgen. Do not edit.
#
# Builds a clean project that uses the packaged crate the way the README says:
# the dependency lines of the README's Installation section and the code of
# its Quick start. Run "cargo package" first.
#
#   bash scripts/consumer-check.sh [WORK_DIR]
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."
root="$(pwd)"
target="${CARGO_TARGET_DIR:-${root}/target}"
package="$(find "${target}/package" -maxdepth 1 -type d -name 'tungo-sdk-*' | sort | tail -n 1)"
if [[ -z "${package}" ]]; then
  echo "error: no packaged crate under ${target}/package; run 'cargo package' first" >&2
  exit 1
fi

work="${1:-$(mktemp -d)}"
mkdir -p "${work}/src"

# The fenced block that follows a heading of README.md.
block() {
  awk -v heading="$1" '
    $0 == heading { found = 1; next }
    found && /^```/ { if (inside) exit; inside = 1; next }
    found && inside { print }
  ' "${root}/README.md"
}

{
  echo '[package]'
  echo 'name = "tungo-sdk-consumer"'
  echo 'version = "0.0.0"'
  echo 'edition = "2021"'
  echo 'publish = false'
  echo
  echo '[workspace]'
  echo
  block '## Installation' | sed -E "s|^tungo-sdk = \"[^\"]*\"|tungo-sdk = { path = \"${package}\" }|"
} >"${work}/Cargo.toml"
block '## Quick start' >"${work}/src/main.rs"

if ! grep -q "^tungo-sdk = { path" "${work}/Cargo.toml" || [[ ! -s "${work}/src/main.rs" ]]; then
  echo "error: could not extract the installation lines or the quick start from README.md" >&2
  exit 1
fi

CARGO_TARGET_DIR="${target}" cargo build --manifest-path "${work}/Cargo.toml"
echo "consumer project builds against ${package}"
